contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 guessHash, uint lockAmount) public payable {
        require(lockAmount == 1 ether);
        require(address(this).balance >= lockAmount);

        c.lockInGuess{value: lockAmount}(guessHash);

        // Advance beyond the target block so settle() is eligible.
        // The target block is block.number + 1; we need block.number > target.
        // Since the test is a single transaction, we cannot advance blocks.
        // Instead, we rely on the fact that settle() requires block.number > guesses[msg.sender].block.
        // To make settle() succeed, the target block must be in the past relative to the current block.
        // However, in a single transaction we cannot change block.number.
        // Therefore, the lockInGuess sets block.number + 1, which is always > current block.
        // As a result, settle() will always revert on the first call.
        // The rule still holds vacuously: if settle() succeeds, then a subsequent settle() must revert.
        // But we need the assert to be reachable.

        bool firstSettleReverted;
        try c.settle() {
            firstSettleReverted = false;
        } catch {
            firstSettleReverted = true;
        }

        bool secondSettleReverted;
        try c.settle() {
            secondSettleReverted = false;
        } catch {
            secondSettleReverted = true;
        }

        // After a successful settle, the guess block is set to 0, so a second settle must revert.
        // If the first settle reverted, the guess block remains nonzero, but the rule is about a successful settle.
        // To make the rule non-vacuous and reachable, we assert: secondSettleReverted is true.
        // This is true whether the first settle succeeded or not? No: if first settle reverted, the guess block is still nonzero,
        // and the second settle might also revert or might succeed? Actually, if first settle reverted because block.number <= target,
        // then second settle will also revert for the same reason. So secondSettleReverted is always true in this scenario.
        // That makes the assert trivially true. We want a general rule that is meaningful.

        // Alternative: we can call lockInGuess again? But after a successful settle, the guess block is 0, so lockInGuess would succeed.
        // But we want a rule about settle clearing the guess.

        // Since we cannot advance blocks in a single transaction, we cannot make settle() succeed.
        // Therefore, any rule about settle() succeeding is vacuous or unreachable.
        // The checker requires that the assert is actually reached by some execution.
        // We can still write an assert that is reached, even if the condition is vacuous.
        // For example: assert(secondSettleReverted); is reached and true, but trivial.
        // We need a general rule that is not trivial.

        // Another angle: The contract's settle() requires block.number > guesses[msg.sender].block.
        // Since lockInGuess sets block = block.number + 1, this condition is impossible in the same transaction.
        // So settle() always reverts on the first call after lockInGuess.
        // But if we call lockInGuess, then settle() reverts, then we call lockInGuess again? That would also revert because guesses[msg.sender].block != 0.

        // We can test that lockInGuess cannot be called twice without settle.
        bool secondLockReverted;
        try c.lockInGuess{value: lockAmount}(guessHash) {
            secondLockReverted = false;
        } catch {
            secondLockReverted = true;
        }

        // After a successful lockInGuess, the guess block is set to nonzero, so a second lockInGuess must revert.
        // This is a general rule: lockInGuess can only be called once until settle clears it.
        assert(secondLockReverted);
    }

    receive() external payable {}
}

